17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Locale;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        this.clinicService.saveOwner(owner);
110	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
111	        headers.setLocation(UriComponentsBuilder.newInstance()
112	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
113	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
114	    }
115	
116	    /**
117	     * Determines whether an owner already exists that uses the same telephone number
118	     * as the given one. Telephone numbers must be unique across all owners. The
119	     * comparison ignores letter case and any surrounding or repeated whitespace.
120	     */
121	    private boolean isDuplicateOwner(Owner owner) {
122	        String telephone = normalize(owner.getTelephone());
123	        return this.clinicService.findAllOwners().stream()
124	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
125	    }
126	
127	    /**
128	     * Determines whether another owner already uses the same email address as the given one.
129	     * Email addresses, when supplied, must be unique across all owners. An owner without an
130	     * email address is never considered a duplicate. The comparison ignores letter case and
131	     * any surrounding or repeated whitespace.
132	     */
133	    private boolean isDuplicateEmail(Owner owner) {
134	        String email = normalize(owner.getEmail());
135	        if (email == null || email.isEmpty()) {
136	            return false;
137	        }
138	        return this.clinicService.findAllOwners().stream()
139	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
140	    }
141	
142	    /**
143	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
144	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
145	     * and "John Smith" normalize to the same key and so count as the same person.
146	     */
147	    private static String normalize(String value) {
148	        if (value == null) {
149	            return null;
150	        }
151	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
157	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
158	        if (currentOwner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        currentOwner.setAddress(ownerFieldsDto.getAddress());
162	        currentOwner.setCity(ownerFieldsDto.getCity());
163	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
164	        currentOwner.setLastName(ownerFieldsDto.getLastName());
165	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
166	        this.clinicService.saveOwner(currentOwner);
167	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Transactional
172	    @Override
173	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        this.clinicService.deleteOwner(owner);
179	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        HttpHeaders headers = new HttpHeaders();
190	        Pet pet = petMapper.toPet(petFieldsDto);
191	        owner.setId(ownerId);
192	        pet.setOwner(owner);
193	        pet.getType().setName(null);
194	        this.clinicService.savePet(pet);
195	        PetDto petDto = petMapper.toPetDto(pet);
196	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
197	            .buildAndExpand(pet.getId()).toUri());
198	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
204	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
205	        if (currentOwner != null) {
206	            Pet currentPet = this.clinicService.findPetById(petId);
207	            if (currentPet != null) {
208	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
209	                currentPet.setName(petFieldsDto.getName());
210	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
211	                this.clinicService.savePet(currentPet);
212	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
221	        HttpHeaders headers = new HttpHeaders();
222	        Visit visit = visitMapper.toVisit(visitFieldsDto);
223	        Pet pet = new Pet();
224	        pet.setId(petId);
225	        visit.setPet(pet);
226	        this.clinicService.saveVisit(visit);
227	        VisitDto visitDto = visitMapper.toVisitDto(visit);
228	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
229	            .buildAndExpand(visit.getId()).toUri());
230	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
231	    }
232	
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner != null) {
239	            Pet pet = owner.getPet(petId);
240	            if (pet != null) {
241	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
242	            }
243	        }
244	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	    }
246	}
